for (const [english, [de, fr, pt]] of Object.entries(routeTranslations)) {
  translations.de[english] = de;
  translations.fr[english] = fr;
  translations['pt-BR'][english] = pt;
}
Object.assign(translations.ru, russianTranslations);
const phraseTranslations = Object.entries(routeTranslations)
  .map(([english, values]) => [english.trim(), values])
  .filter(([english]) => english.length >= 12)
  .sort((a, b) => b[0].length - a[0].length);

export function resolveLanguage(stored, preferred = []) {
  if (languages[stored]) return stored;
  for (const requested of preferred) {
    const exact = Object.keys(languages).find((code) => code.toLowerCase() === requested.toLowerCase());
    if (exact) return exact;
    const base = requested.toLowerCase().split('-')[0];
    const match = Object.keys(languages).find((code) => code.toLowerCase().split('-')[0] === base);
    if (match) return match;
  }
  return 'en';
}

let stored = '';
try { stored = globalThis.window?.localStorage?.getItem('folding.language') || ''; } catch {}
export const language = resolveLanguage(stored, globalThis.navigator?.languages || []);

export function t(text) {
  if (typeof text !== 'string' || language === 'en') return text;
  const leading = text.match(/^\s*/)[0];
  const trailing = text.match(/\s*$/)[0];
  const core = text.trim();
  const exact = translations[language]?.[text] || translations[language]?.[core];
  if (exact) return leading + exact.trim() + trailing;
  let translated = core;
  for (const [english] of phraseTranslations) {
    const replacement = translations[language]?.[english];
    if (replacement && translated.includes(english)) translated = translated.replaceAll(english, replacement.trim());
  }
  return leading + translated + trailing;
}

export function tr(text, ...values) {
  return t(text).replace(/\{(\d+)\}/g, (_, i) => values[i] ?? '');
}

function translateShell(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const value = node.data.trim();
    const translated = t(value);
    if (translated !== value) node.data = node.data.replace(value, translated);
  }
  for (const node of root.querySelectorAll('[title], [aria-label], [placeholder]')) {
    for (const attr of ['title', 'aria-label', 'placeholder']) {
      if (node.hasAttribute(attr)) node.setAttribute(attr, t(node.getAttribute(attr)));
    }
  }
}

export function initI18n() {
  document.documentElement.lang = language;
  document.title = t(document.title);
  translateShell(document.body);
  const select = document.getElementById('language-select');
  select.value = language;
  select.setAttribute('aria-label', t('Language'));
  select.addEventListener('change', () => {
    localStorage.setItem('folding.language', select.value);
    location.reload();
  });
}
